def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    by_color = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            minr = min(y for y, x in cells)
            minc = min(x for y, x in cells)
            shape = [(y - minr, x - minc) for y, x in cells]
            by_color.setdefault(color, []).append({
                'shape': shape,
                'size': len(cells),
                'height': max(y for y, x in shape) + 1,
                'width': max(x for y, x in shape) + 1,
            })

    colors = sorted(by_color, key=lambda color: (sum(o['size'] for o in by_color[color]), color))
    left, right = colors
    left_width = max(o['width'] for o in by_color[left])
    xbase = {left: 0, right: left_width + 1}
    out = [[0] * w for _ in range(h)]
    for color in colors:
        objects = sorted(by_color[color], key=lambda o: o['size'])
        # Stack smallest-to-largest from top to bottom, with one empty row between objects,
        # and align the bottom of the largest object with the grid's bottom edge.
        total_height = sum(o['height'] for o in objects) + len(objects) - 1
        y = h - total_height
        for obj in objects:
            for dy, dx in obj['shape']:
                yy, xx = y + dy, xbase[color] + dx
                if 0 <= yy < h and 0 <= xx < w:
                    out[yy][xx] = color
            y += obj['height'] + 1
    return out
